class _CalcError(Exception):
    pass


def calc(expr: str) -> int | str:
    n = len(expr)
    pos = 0

    def skip_spaces() -> None:
        nonlocal pos
        while pos < n and expr[pos] == " ":
            pos += 1

    def parse_atom() -> int:
        nonlocal pos
        skip_spaces()
        if expr[pos] == "(":
            pos += 1
            val = parse_expr()
            skip_spaces()
            pos += 1  # ')'
            return val
        start = pos
        while pos < n and expr[pos].isdigit():
            pos += 1
        return int(expr[start:pos])

    def parse_power() -> int:
        nonlocal pos
        bases = [parse_atom()]
        negs: list[bool] = []
        while True:
            skip_spaces()
            if pos < n and expr[pos] == "^":
                pos += 1
                neg = False
                while True:
                    skip_spaces()
                    if pos < n and expr[pos] == "-":
                        neg = not neg
                        pos += 1
                    else:
                        break
                negs.append(neg)
                bases.append(parse_atom())
            else:
                break

        res = bases[-1]
        for i in range(len(negs) - 1, -1, -1):
            if negs[i]:
                res = -res
            if res < 0:
                raise _CalcError()
            res = pow(bases[i], res)
        return res

    def parse_unary() -> int:
        nonlocal pos
        neg = False
        while True:
            skip_spaces()
            if pos < n and expr[pos] == "-":
                neg = not neg
                pos += 1
            else:
                break
        val = parse_power()
        return -val if neg else val

    def parse_term() -> int:
        nonlocal pos
        val = parse_unary()
        while True:
            skip_spaces()
            if pos < n and expr[pos] in "*/%":
                op = expr[pos]
                pos += 1
                rhs = parse_unary()
                if op == "*":
                    val *= rhs
                elif op == "/":
                    if rhs == 0:
                        raise _CalcError()
                    q = abs(val) // abs(rhs)
                    val = -q if (val < 0) != (rhs < 0) else q
                else:
                    if rhs == 0:
                        raise _CalcError()
                    r = abs(val) % abs(rhs)
                    val = -r if val < 0 else r
            else:
                break
        return val

    def parse_expr() -> int:
        nonlocal pos
        val = parse_term()
        while True:
            skip_spaces()
            if pos < n and expr[pos] in "+-":
                op = expr[pos]
                pos += 1
                rhs = parse_term()
                if op == "+":
                    val += rhs
                else:
                    val -= rhs
            else:
                break
        return val

    try:
        return parse_expr()
    except _CalcError:
        return "error"
